import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { Circle } from "@remotion/shapes";
// [Start Google Fonts Loader]
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;500;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
// [End Google Fonts Loader]



export type WalletCardProps = Record<string, any>;

const WalletCard: React.FC<WalletCardProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  cardColor = "#10b981", // Emerald green
  balance = 10000,
  title = "Wallet",
  subtitle = "Mastercard ending 4853",
  currencySymbol = "$",
  durationInSeconds = 8,
}) => {
  useFontLoader(["Inter", "DM Sans"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // --- Theme & Layout Constants ---
  // Increased container size limits to make the component bigger
  const containerWidth = Math.min(width * 0.9, 850); 
  const containerHeight = Math.min(height * 0.55, 550);
  const cardHeight = containerHeight * 0.75; // Used for calculation reference if needed
  const borderRadius = 24;
  
  // --- Derived Colors ---
  const bgColor = transparentBackground ? "transparent" : backgroundColor;
  const cardGradient = `linear-gradient(135deg, ${cardColor} 0%, ${cardColor}dd 100%)`;

  // --- Animations ---

  // 1. Container Slide Up & Fade
  const containerSpring = spring({
    frame: frame,
    fps,
    config: {
      damping: 15,
      stiffness: 100,
    },
  });
  
  const containerOpacity = interpolate(frame, [0, 15], [0, 1], {
    extrapolateRight: "clamp",
  });
  
  const containerY = interpolate(containerSpring, [0, 1], [50, 0]);

  // 2. Text Reveal (Header)
  const headerOpacity = interpolate(frame, [10, 30], [0, 1], {
    extrapolateRight: "clamp",
  });
  const headerY = interpolate(frame, [10, 30], [10, 0], {
    extrapolateRight: "clamp",
    easing: (t) => t * (2 - t), // easeOutQuad
  });

  // 3. Green Card Rise
  // Adjusted spring physics for a "slight bounce" without overextension
  const cardRiseSpring = spring({
    frame: frame - 15, // Delay
    fps,
    config: {
      damping: 18,   // Increased damping to reduce bounce
      stiffness: 90, // Increased stiffness for snappier movement
    },
  });
  
  const cardY = interpolate(cardRiseSpring, [0, 1], [containerHeight, 0]);

  // 4. Logo Circles Pop
  const circle1Scale = spring({
    frame: frame - 40,
    fps,
    config: {
      damping: 10,
      stiffness: 200,
    },
  });
  
  const circle2Scale = spring({
    frame: frame - 45,
    fps,
    config: {
      damping: 10,
      stiffness: 200,
    },
  });

  // 5. Balance Counter
  const countUpValue = interpolate(frame, [45, 90], [0, balance], {
    extrapolateRight: "clamp",
    easing: (t) => 1 - Math.pow(1 - t, 3), // easeOutCubic
  });
  const displayBalance = Math.floor(countUpValue).toLocaleString();

  // 6. Balance Text Fade
  const balanceOpacity = interpolate(frame, [45, 65], [0, 1], {
    extrapolateRight: "clamp",
  });

  // 7. Idle Float Animation for Green Card
  const idleFloat = Math.sin(frame / 40) * 5; 
  const idleY = interpolate(frame, [80, 120], [0, idleFloat], {
    extrapolateLeft: "clamp",
  }); 

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Inter, sans-serif",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      {/* Widget Container */}
      <div
        style={{
          width: containerWidth,
          height: containerHeight,
          backgroundColor: "rgba(28, 28, 30, 0.95)", // Dark grey frosted look
          borderRadius: borderRadius,
          position: "relative",
          overflow: "hidden", 
          boxShadow: "0 30px 60px rgba(0,0,0,0.6)",
          opacity: containerOpacity,
          transform: `translateY(${containerY}px)`,
          display: "flex",
          flexDirection: "column",
          padding: "24px", // Full padding around ensures card is not cut off
        }}
      >
        {/* Header Section */}
        <div
          style={{
            opacity: headerOpacity,
            transform: `translateY(${headerY}px)`,
            marginBottom: 20,
            zIndex: 10, 
          }}
        >
          <div
            style={{
              color: "#ffffff",
              fontSize: 28, // Slightly larger text
              fontWeight: 600,
              letterSpacing: "-0.5px",
              marginBottom: 4,
            }}
          >
            {title}
          </div>
          <div
            style={{
              color: "#8e8e93", // iOS System Grey
              fontSize: 18, // Slightly larger text
              fontWeight: 400,
            }}
          >
            {subtitle}
          </div>
        </div>

        {/* Green Card */}
        <div
          style={{
            flex: 1, 
            background: cardGradient,
            borderRadius: 20, // Rounded all corners
            marginBottom: 0, // Removed negative margin to fix cut-off
            position: "relative",
            transform: `translateY(${cardY + (frame > 80 ? idleY : 0)}px)`,
            padding: 28, // Increased internal padding
            display: "flex",
            flexDirection: "column",
            justifyContent: "space-between",
            boxShadow: "0 10px 40px rgba(0,0,0,0.2)",
          }}
        >
          {/* Logo Section */}
          <div style={{ display: "flex", gap: 0 }}>
            <div style={{ transform: `scale(${circle1Scale})` }}>
              <Circle
                radius={24} // Larger circles
                fill="#EB001B" // Mastercard Red
                style={{ mixBlendMode: "normal" }}
              />
            </div>
            <div style={{ transform: `scale(${circle2Scale})`, marginLeft: -14 }}>
              <Circle
                radius={24} // Larger circles
                fill="#F79E1B" // Mastercard Orange
                style={{ opacity: 0.9 }} 
              />
            </div>
          </div>

          {/* Balance Section */}
          <div style={{ marginTop: 40, marginBottom: 10 }}>
            <div
              style={{
                color: "white",
                fontSize: 64, // Larger balance font
                fontFamily: "DM Sans, sans-serif",
                fontWeight: 700,
                lineHeight: 1,
                marginBottom: 8,
                opacity: balanceOpacity,
                transform: `translateX(${interpolate(balanceOpacity, [0, 1], [-20, 0])}px)`,
              }}
            >
              {currencySymbol}{displayBalance}
            </div>
            <div
              style={{
                color: "rgba(255,255,255,0.8)",
                fontSize: 20,
                fontWeight: 500,
                opacity: balanceOpacity,
              }}
            >
              Total Balance
            </div>
          </div>
          
          {/* Shine Effect */}
          <div
            style={{
              position: "absolute",
              top: 0,
              left: 0,
              width: "200%",
              height: "100%",
              background: "linear-gradient(90deg, transparent 0%, rgba(255,255,255,0.1) 50%, transparent 100%)",
              transform: `skewX(-20deg) translateX(${interpolate(frame, [60, 120], [-500, 500])}px)`,
              pointerEvents: "none",
            }}
          />
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default WalletCard;